-- Acrescenta questões autorais de crase e seus gabaritos.
begin;
select public.admin_import_questions('[{"id":"520e700d65438ea92d0485d4b8d40e72","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Complete a frase. “A funcionária encaminhou o pedido ___ supervisora responsável.”","options":["a","á","à","há"],"correct_index":2,"explanation":"Encaminha-se algo a alguém. A preposição “a” e o artigo de “a supervisora” formam “à”.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"4a3de3f6d19a0d62c5184d3a3998984f","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Qual alternativa apresenta a fusão da preposição “a” com o artigo feminino plural?","options":["O diretor se referiu às servidoras do setor.","O diretor elogiou as servidoras do setor.","O diretor falou com as servidoras do setor.","O diretor chamou duas servidoras do setor."],"correct_index":0,"explanation":"“Referir-se” rege “a”. Com o artigo definido feminino plural, forma-se “às”.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"dcf53850cd54a3c7e8a18a73f5d0adff","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Complete a frase. “A comissão recorreu ___ documento que já havia sido citado.”","options":["aquele","áquele","naquele","àquele"],"correct_index":3,"explanation":"“Recorrer” rege “a” nesse contexto. A preposição se funde com o início de “aquele”.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"3a31784c2b0f824edf6e46bc095f1e1d","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Qual alternativa segue a norma-padrão no emprego do demonstrativo neutro?","options":["Não me oponho aquilo.","Não me oponho ao aquilo.","Não me oponho àquilo.","Não me oponho áquilo."],"correct_index":2,"explanation":"“Opor-se” rege “a”. A combinação com “aquilo” resulta em “àquilo”.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"dd723c492bae124cd0e2381f3596e205","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Complete a frase. “A solução proposta é equivalente ___ de ontem.”","options":["a","à","ao","há"],"correct_index":1,"explanation":"“Equivalente” rege “a”. O demonstrativo feminino equivale a “aquela solução”.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"3d9f49b1211a7c7d225f57f9a56ae30d","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Complete a frase. “Entre as candidatas, deram preferência ___ que tinham experiência.”","options":["às","as","aos","há"],"correct_index":0,"explanation":"O termo “preferência” rege “a”. “As” significa “aquelas candidatas”.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"4fd6b2ff1f4a14d03a7252a50505e35b","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Complete a frase. “A norma ___ o parecer faz referência entrou em vigor em janeiro.”","options":["a qual","na qual","pela qual","à qual"],"correct_index":3,"explanation":"“Fazer referência” rege “a”. Com o relativo “a qual”, forma-se “à qual”.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"937718639ce9d62b042aba220ea89c6b","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Em qual período o pronome relativo recebe corretamente o acento grave?","options":["As regras às quais o grupo obedeceu eram claras.","As regras às quais o grupo leu eram claras.","As regras às quais o grupo discutiu eram claras.","As regras às quais o grupo alterou eram claras."],"correct_index":0,"explanation":"Só “obedecer” rege a preposição “a” nesses períodos. Os demais verbos recebem objeto direto.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"e5ca511be889f93bb3d9855fc0d9ef3e","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Qual alternativa contém uma locução adverbial grafada corretamente?","options":["Saiu as pressas.","Virou á direita.","O pagamento foi feito à vista.","O setor abre a noite."],"correct_index":2,"explanation":"“À vista” é locução adverbial e recebe acento grave.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"6593feca441c4f4457afb9030b204619","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Complete a frase. “Os voluntários ficaram ___ procura de materiais para a campanha.”","options":["ao","a","á","à"],"correct_index":3,"explanation":"A expressão “à procura de” é uma locução prepositiva consagrada.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"49a3f87d4452f8cf03aec027d76b65d5","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Assinale a alternativa em que a locução conjuntiva está grafada corretamente.","options":["A medida que chovia, o rio subia.","À medida que chovia, o rio subia.","Á medida que chovia, o rio subia.","Há medida que chovia, o rio subia."],"correct_index":1,"explanation":"A locução conjuntiva proporcional “à medida que” recebe acento grave.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"64001cc165a0dfea85e992b08a93bf55","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Em qual alternativa a indicação de horário está escrita corretamente?","options":["A prova começará às 14h.","A prova foi marcada para às 14h.","A sala fica aberta desde às 14h.","A inscrição termina após às 14h."],"correct_index":0,"explanation":"Indica-se o horário com “às 14h”. Depois de “para”, “desde” e “após”, usa-se apenas o artigo “as”.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"e98c5d3bce77a95ff4404b0c3088704d","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Complete o intervalo. “O atendimento ocorrerá entre ___ 9h e ___ 11h.”","options":["às / às","as / às","às / as","as / as"],"correct_index":3,"explanation":"“Entre” introduz o intervalo. Os dois horários vêm precedidos do artigo “as”.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"eeafc52e0446d08d40be30de45fe54cc","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Qual alternativa emprega o acento grave para indicar estilo, com “à maneira de” subentendido?","options":["O cronista escreveu à Machado de Assis.","O estudante foi à pé.","A fábrica vendeu o produto à prazo.","O motorista dirigiu à oitenta quilômetros por hora."],"correct_index":0,"explanation":"A forma “à Machado de Assis” indica o estilo do escritor, com elipse de “à maneira de”.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"ff687109d69b23f90982d6ef45cb714a","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Em qual alternativa o acento grave se justifica pela ideia de “à moda de”?","options":["Enviou o prato à domicílio.","Serviu arroz à grega.","Pagou o almoço à prazo.","Temperou o prato à gosto."],"correct_index":1,"explanation":"Em “arroz à grega”, subentende-se “à moda grega”.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"71c8eadfba6ac4632f7aeec531d2cc80","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Complete as lacunas. “A pesquisadora viajou ___ Itália e depois foi ___ Brasília.”","options":["a / à","à / à","à / a","a / a"],"correct_index":2,"explanation":"Diz-se “voltar da Itália”, com artigo, e “voltar de Brasília”, sem artigo nesse uso.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"7e7436d79646f866a0279a69e08ccc71","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Qual frase usa corretamente o acento grave antes de um nome de lugar?","options":["Fui à Curitiba.","Voltei à Lisboa.","Cheguei à Roma.","Viajei à Bahia."],"correct_index":3,"explanation":"A Bahia admite artigo feminino nesse uso. Os demais nomes, empregados sem especificação, vêm sem artigo nos exemplos.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"9415b66b6a550e06b3de3c6c267e9083","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Complete a frase, considerando “casa” como a própria moradia no primeiro caso. “Voltei ___ casa e depois fui ___ casa da minha avó.”","options":["a / à","à / a","à / à","a / a"],"correct_index":0,"explanation":"No primeiro caso, “casa” significa o próprio lar e aparece sem artigo. No segundo, a expressão “da minha avó” especifica a casa.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"40514c4b4e781adb4a88887a5b61743d","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Complete a frase. “Depois de semanas a bordo, os marinheiros desceram ___ terra.”","options":["à","a","á","há"],"correct_index":1,"explanation":"Em oposição a “a bordo”, “terra” aparece sem artigo nesse emprego.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"6719e6c0f07bdc5fe4748149063143de","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Indique a forma recomendada quando a distância é determinada. “O observador ficou ___ distância de duzentos metros do portão.”","options":["a","á","à","há"],"correct_index":2,"explanation":"Na expressão “à distância de”, seguida de uma medida determinada, usa-se o acento grave.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"bb8cad7e5920512185d6171a94dbcd4c","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Em qual alternativa o acento grave pode ser omitido sem ferir a norma-padrão?","options":["Chegamos às três horas.","Respondi àquela pergunta.","Entregamos a encomenda à minha irmã.","Estávamos à espera do resultado."],"correct_index":2,"explanation":"O artigo antes do possessivo feminino singular pode ser facultativo. São possíveis “a minha irmã” e “à minha irmã”.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"2794b73cc470f283589a4733c2e47aaf","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Em qual caso se admitem tanto a forma com acento grave quanto a forma sem ele?","options":["Deu o recado a Ana, com o nome próprio sem determinante.","Começou a trabalhar após o almoço.","Chegou às oito horas da manhã.","Respondeu àquela pergunta do formulário."],"correct_index":0,"explanation":"Diante de nome próprio feminino, o artigo pode ser facultativo. Por isso, “a Ana” e “à Ana” são possíveis.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"fd4a21be8aeea27c599719cb4be422d4","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Qual par contém duas construções aceitas depois de “até”?","options":["Até à praia / até há praia.","Até a praia / até á praia.","Até a praia / até para praia.","Até a praia / até à praia."],"correct_index":3,"explanation":"Admite-se “até a praia”, com a preposição “até” e o artigo, ou “até à praia”, com “até a” e o artigo.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"9f9e74f4ec70f1ddb492f2311c6657c6","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Qual alternativa usa o acento grave para marcar o instrumento utilizado?","options":["A autora escreveu o manuscrito à máquina.","A autora começou à escrever o manuscrito.","A autora enviou o manuscrito à ele.","A autora enviou o manuscrito à uma editora."],"correct_index":0,"explanation":"“À máquina” é locução de instrumento consagrada. Nos demais casos, falta o artigo feminino definido exigido para a fusão.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"3fdc8fcefb57f9896c5e7d97a051f3c4","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"O que significa “a fome” em “Depois da viagem, o passageiro matou a fome”?","options":["Causa da morte do passageiro.","Objeto direto, no sentido de saciar-se.","Instrumento usado na viagem.","Modo como o passageiro viajou."],"correct_index":1,"explanation":"“Matar a fome” significa saciar-se. “A fome” funciona como objeto direto.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"d9e074ff15bcfe26aaa2aee7da54addb","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Assinale a frase escrita corretamente quanto ao emprego do acento grave.","options":["Os atletas voltaram à pé.","Começou à nevar de manhã.","Entreguei o envelope à ela.","Os diretores ficaram frente a frente."],"correct_index":3,"explanation":"“Frente a frente” é construção de palavras repetidas. Nos outros casos, o acento foi usado indevidamente.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"6558909d67407a179dc0ae4aa34f0360","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Qual alternativa exige acento grave na lacuna?","options":["A decisão se aplica ___ qualquer pessoa.","O servidor se dirigiu ___ senhora que presidia a mesa.","O aviso se refere ___ essa norma.","A carta foi dirigida ___ Vossa Senhoria."],"correct_index":1,"explanation":"“Senhora” admite artigo feminino. “Dirigir-se” rege a preposição “a”.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"6f2571827645a47f4090ab6ff04c0969","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Complete a frase, em referência a candidatas em geral. “O edital se destina ___ candidatas com experiência.”","options":["a","à","as","há"],"correct_index":0,"explanation":"“Destinar-se” rege “a”. Como o plural indeterminado vem sem artigo, usa-se só a preposição.","origin":"Autoral · curadoria inicial","editorial_status":"initial"}]'::jsonb) as imported;
commit;
